// Rakit payload POST /api/v1/prakiraan-beban/ dari baris Google Sheets.
//
// Header sheet yang diharapkan: Tanggal | Jam | MW  (case-insensitive).
// - Jam boleh "HH:MM" atau "HH:MM:SS"; boleh juga kolom "Menit" (0..1439).
// - MW boleh pakai koma desimal; sel kosong dilewati.
// - Hanya baris H dan H+1 yang dikirim — kurva hari lampau TIDAK ditimpa,
//   karena histori itulah yang dipakai menghitung akurasi di FASOP.

const ZONA = 'Asia/Makassar';
const hariIni = DateTime.now().setZone(ZONA).toISODate();
const besok = DateTime.now().setZone(ZONA).plus({ days: 1 }).toISODate();
const DIIZINKAN = new Set([hariIni, besok]);

/** Ambil nilai kolom tanpa peduli besar-kecil huruf / spasi. */
function kolom(row, ...nama) {
  const peta = {};
  for (const k of Object.keys(row)) peta[k.trim().toLowerCase()] = row[k];
  for (const n of nama) {
    const v = peta[n.toLowerCase()];
    if (v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return null;
}

/** Tanggal sheet -> 'YYYY-MM-DD'. Menerima ISO, DD/MM/YYYY, dan Date. */
function normalTanggal(v) {
  if (v == null || String(v).trim() === '') return null;
  if (v instanceof Date) return DateTime.fromJSDate(v).setZone(ZONA).toISODate();
  const s = String(v).trim();
  for (const fmt of ['yyyy-MM-dd', 'dd/MM/yyyy', 'd/M/yyyy', 'dd-MM-yyyy']) {
    const d = DateTime.fromFormat(s, fmt, { zone: ZONA });
    if (d.isValid) return d.toISODate();
  }
  const iso = DateTime.fromISO(s, { zone: ZONA });
  return iso.isValid ? iso.toISODate() : null;
}

const data = [];
const dilewati = [];

for (const item of $input.all()) {
  const row = item.json;

  const mwMentah = kolom(row, 'mw', 'beban', 'beban (mw)', 'prakiraan');
  if (mwMentah == null) continue;                 // sel kosong: wajar, lewati

  const jam = kolom(row, 'jam', 'waktu', 'time');
  const menit = kolom(row, 'menit', 'minute');
  if (jam == null && menit == null) continue;     // baris judul / baris kosong

  const tanggal = normalTanggal(kolom(row, 'tanggal', 'date'));
  // Sheet satu hari tanpa kolom Tanggal -> tanggal null, dipakai default
  // server (hari ini). Kalau ada kolom Tanggal, saring ke H dan H+1 saja.
  if (tanggal !== null && !DIIZINKAN.has(tanggal)) {
    dilewati.push(tanggal);
    continue;
  }

  const baris = { mw: mwMentah };
  if (tanggal !== null) baris.tanggal = tanggal;
  if (menit != null) baris.menit = menit;
  else baris.jam = String(jam).trim();

  data.push(baris);
}

if (data.length === 0) {
  throw new Error('Tidak ada baris prakiraan H/H+1 yang terbaca dari sheet — '
    + 'periksa nama kolom (Tanggal/Jam/MW) dan isi sheet.');
}

return [{ json: { sumber: 'roh-sulbagsel', data, _dilewati: dilewati.length } }];
